 async applyRoomCommand(seat:number,command:Command){if(!this.data?.coinEnabled||this.session!.state.phase!=='calling'||command.type!=='call'||this.data.coinDeal===this.session!.state.matchId)return this.session!.apply(seat,command);const candidate=new Session(this.session!.state);candidate.restore(this.session!.seq,[...this.session!.seen]);const receipt=candidate.apply(seat,command);if(!(await this.coinFunding(false)))throw Error('Waiting for table refill.');const tier=tableTier(this.data.tableChoice?.tier??2500),cap=this.stakeLimit(),stake=command.stake??tier.minStake;if(!Number.isSafeInteger(stake)||stake<tier.minStake||stake>cap||(stake-tier.minStake)%tier.step)throw Error('Choose a stake between '+tier.minStake+' and '+cap+'.');if(candidate.state.phase==='playing'){const previous=this.data.tableChoice;this.data.tableChoice=tableChoice({tier:tier.id,stake});try{await this.coinCall('reserve',{deal:candidate.state.matchId,players:this.data.uids});}catch(e){this.data.tableChoice=previous;throw e;}this.data.coinDeal=candidate.state.matchId;this.data.coinEntryAt=Date.now();this.data.coinBalances=this.data.coinBalances!.map(n=>n-stake);}this.session=candidate;return receipt;}
