 async flushFriendAdmissions(){if(!this.data)return;for(const admission of [...(this.data.friendAdmissions||[])]){try{await completeFriendAdmission(this.env,admission.id,this.data.code,admission.target,admission.sender,this.data.uids.includes(admission.target)&&!this.life.closed,admission.previousRoom);this.data.friendAdmissions=this.data.friendAdmissions?.filter(a=>a.id!==admission.id);await this.persist();}catch{/* Persisted admission retries on the next room alarm. */}}}
