  if(path==='/coin-action')return coinAction(this.env.DB,uid,await req.json());
  if(path==='/coin-topup'){const body=await req.json<{id:string;amount:number;autoTopup?:boolean}>();if(!this.data?.coinEnabled||!this.data.uids.includes(uid)||this.life.closed)return json({error:'No public table seat'},409);const r=await socialRPC(this.env,'__coins','coin-action',uid,{action:'topup',id:body.id,room:this.data.code,amount:body.amount,autoTopup:body.autoTopup,choice:this.data.tableChoice});if(r.ok){await this.coinFunding(false);await this.persist();this.broadcast();}return r;}
  if(path.startsWith('/chat-'))return chatAction(this.env,uid,path.slice(6),await req.json());
  if(path==='/player-report')return submitPlayerReport(this.env,uid,await req.json());
  if(path==='/social-action')return socialAction(this.env,uid,await req.json());
  if(path==='/device-presence'){const lease=await this.ctx.storage.get<DeviceLease>('device-lease');return json({online:!!lease&&lease.expires-90000+35000>Date.now(),...(lease?.room?{room:lease.room}:{})});}
  if(path==='/social-room'){const {room,expectedRoom}=await req.json<{room:string|null;expectedRoom?:string|null}>();const lease=await this.ctx.storage.get<DeviceLease>('device-lease');if(expectedRoom!==undefined&&(lease?.room||null)!==expectedRoom)return json({ok:false});if(lease&&room===null){delete lease.room;await this.ctx.storage.put('device-lease',lease);}if(lease&&room&&/^[A-F0-9]{8}$/.test(room))await this.ctx.storage.put('device-lease',{...lease,room});return json({ok:true});}
